package android.graphics;import java.io.*;import javax.imageio.*;import javax.imageio.stream.*;import java.util.*;public final class BitmapFactory{public static final class Options{public boolean inJustDecodeBounds;public int outWidth=-1,outHeight=-1;public String outMimeType;}public static Bitmap decodeByteArray(byte[] bytes,int offset,int length){try{var image=ImageIO.read(new ByteArrayInputStream(bytes,offset,length));return image==null?null:new Bitmap(image);}catch(IOException e){return null;}}public static Bitmap decodeByteArray(byte[] bytes,int offset,int length,Options options){try(ImageInputStream input=ImageIO.createImageInputStream(new ByteArrayInputStream(bytes,offset,length))){Iterator<ImageReader> readers=ImageIO.getImageReaders(input);if(!readers.hasNext())return null;ImageReader reader=readers.next();try{reader.setInput(input);options.outWidth=reader.getWidth(0);options.outHeight=reader.getHeight(0);options.outMimeType=reader.getFormatName().equalsIgnoreCase("JPEG")?"image/jpeg":"image/png";return options.inJustDecodeBounds?null:new Bitmap(reader.read(0));}finally{reader.dispose();}}catch(Exception e){return null;}}}
